/**
 * @brief Reads the touch tag and updates page number and page update status accordingly.
 * 
 * This function reads the touch tag value from the FT810 controller register.
 * Based on the touch tag value, it updates the page number variable to navigate to a specific page.
 * If the touch tag value is between 1 and 4 (inclusive), it sets the page update status to 1.
 * 
 * @return The touch tag value read from the controller.
 */
unsigned char Boardoza_FT810::read_touch(void)
{
  unsigned char touch_tag;
    
	touch_tag = read8(REG_TOUCH_TAG);

	switch(touch_tag)
	{
		case 1:			
		page_number=2;
		break;
				
        case 2:
		page_number=3;
        break;
						
		case 3:
		page_number=4;
		break;
				
        case 4:
		page_number=1;
        break;
	}

	if(touch_tag > 0 && touch_tag < 5)
	{
		page_update=1;
	}

  	return touch_tag;
}

/**
 * @brief Sends a text string to be displayed on the screen.
 *
 * @param text The text string to be displayed.
 *
 * @details This function sends a text string to the FT800 chip to display it on the screen. It iterates through the text
 * string in chunks of four characters at a time, converting each chunk to a 32-bit value and writing it to the RAM_CMD register.
 * The function continues this process until a null terminator (0) is encountered in the text string, indicating the end of the string.
 */
void Boardoza_FT810::sendText(char text_content[])
{
	unsigned char i;
	unsigned char string_done;


	i=0;
	string_done=0;
	while(string_done==0)
	{
    	write32(RAM_CMD + cmdOffset,(text_content[(i*4)+3]<<24) | (text_content[(i*4)+2]<<16) | (text_content[(i*4)+1]<<8) | text_content[i*4]);

    	cmdOffset = incrementCMDOffset(cmdOffset, 4);
		
			if((text_content[(i*4)+3]==0)||(text_content[(i*4)+2]==0)||(text_content[(i*4)+1]==0)||(text_content[i*4]==0))
			{
				string_done=1;
			}
			i++;
	}
	
}

/**
 * @brief Adds a button to the screen with specified colors, dimensions, text content, and touch functionality.
 *
 * This function adds a button to the screen with different visual states for press and release events.
 * The button can have gradient color, text color, and specific touch functionality based on the touch number.
 * 
 * @param FG_COLOR_press The foreground color of the button when pressed.
 * @param FG_COLOR_release The foreground color of the button when released.
 * @param GRAD_COLOR The gradient color of the button.
 * @param TEXT_COLOR The color of the text on the button.
 * @param touch_number The touch number associated with the button.
 * @param X_start The x-coordinate of the top-left corner of the button.
 * @param Y_start The y-coordinate of the top-left corner of the button.
 * @param width The width of the button.
 * @param height The height of the button.
 * @param font The font style of the text on the button.
 * @param text_content The content of the text displayed on the button.
 */
void Boardoza_FT810::add_button(unsigned long FG_COLOR_press,unsigned long FG_COLOR_release,unsigned long GRAD_COLOR,unsigned long TEXT_COLOR, unsigned char touch_number,unsigned long X_start,unsigned long Y_start,unsigned long width,unsigned long height,unsigned char font, char text_content[])
{
   unsigned char read_value=100;	

	write32(RAM_CMD + cmdOffset, CMD_FGCOLOR);

	cmdOffset = incrementCMDOffset(cmdOffset, 4);        // Update the command pointer

    read_value=read8(REG_TOUCH_TAG);

	if(read_value==touch_number)
	{
		write32(RAM_CMD + cmdOffset, FG_COLOR_press);
		cmdOffset = incrementCMDOffset(cmdOffset, 4);        // Update the command pointer
	}
	else
	{
		write32(RAM_CMD + cmdOffset, FG_COLOR_release);	//	foregroundcolor						
		cmdOffset = incrementCMDOffset(cmdOffset, 4);        // Update the command pointer
	}

	write32(RAM_CMD + cmdOffset, CMD_GRADCOLOR);

	cmdOffset = incrementCMDOffset(cmdOffset, 4);        // Update the command pointer

	write32(RAM_CMD + cmdOffset, GRAD_COLOR);//gradcolor

	cmdOffset = incrementCMDOffset(cmdOffset, 4);        // Update the command pointer


	write32(RAM_CMD + cmdOffset, (DL_COLOR_RGB |TEXT_COLOR ));//textcolor

	cmdOffset = incrementCMDOffset(cmdOffset, 4);

	write32(RAM_CMD + cmdOffset, TAG_MASK(1));
	cmdOffset = incrementCMDOffset(cmdOffset, 4);
	write32(RAM_CMD + cmdOffset, TAG(touch_number));
	cmdOffset = incrementCMDOffset(cmdOffset, 4);
	
	write32(RAM_CMD + cmdOffset, COLOR_A(255) );

	cmdOffset = incrementCMDOffset(cmdOffset, 4);

	write32(RAM_CMD + cmdOffset, (CMD_BUTTON));
																									// End the point
	cmdOffset = incrementCMDOffset(cmdOffset, 4);        // Update the command pointer

	write32(RAM_CMD + cmdOffset, X_start|(Y_start<<16));//y start, x start
												  // End the point
	cmdOffset = incrementCMDOffset(cmdOffset, 4);        // Update the command pointer

	write32(RAM_CMD + cmdOffset, width|(height<<16));//height,witdh
												 // End the point
	cmdOffset = incrementCMDOffset(cmdOffset, 4);        // Update the command pointer

	write32(RAM_CMD + cmdOffset, font);//options, font
												  // End the point
	cmdOffset = incrementCMDOffset(cmdOffset, 4);        // Update the command pointer
	
	
	sendText(text_content);

	write32(RAM_CMD + cmdOffset, TAG_MASK(0));
	cmdOffset = incrementCMDOffset(cmdOffset, 4);

}

/**
 * @brief Adds a number display to the screen with specified text color, position, font, and value.
 *
 * This function adds a number display to the screen with the given text color, position, font style,
 * and numerical value to be displayed.
 * 
 * @param TEXT_COLOR The color of the number text.
 * @param X_start The x-coordinate of the top-left corner of the number display.
 * @param Y_start The y-coordinate of the top-left corner of the number display.
 * @param font The font style of the number text.
 * @param value The numerical value to be displayed.
 */
void Boardoza_FT810::add_number(unsigned long TEXT_COLOR,unsigned long X_start,unsigned long Y_start,unsigned char font, unsigned long value)
{
    write32(RAM_CMD + cmdOffset, (DL_COLOR_RGB | TEXT_COLOR));//text color

    cmdOffset = incrementCMDOffset(cmdOffset, 4);

    write32(RAM_CMD + cmdOffset, COLOR_A(255));//transparency

    cmdOffset = incrementCMDOffset(cmdOffset, 4);

    write32(RAM_CMD + cmdOffset, (CMD_NUMBER));
	                                                  // End the point
	cmdOffset = incrementCMDOffset(cmdOffset, 4);        // Update the command pointer

	write32(RAM_CMD + cmdOffset, X_start|(Y_start<<16));//y start, x start 
												  // End the point
	cmdOffset = incrementCMDOffset(cmdOffset, 4);        // Update the command pointer


	write32(RAM_CMD + cmdOffset, font);//options, font
												  // End the point
	cmdOffset = incrementCMDOffset(cmdOffset, 4);        // Update the command pointer

	write32(RAM_CMD + cmdOffset, value);
												  // End the point
	cmdOffset = incrementCMDOffset(cmdOffset, 4);        // Update the command pointer

}

