/**
 * @brief Draws an image on the screen using the specified image number from the picture table.
 *
 * This function draws an image on the screen by setting various parameters such as bitmap handle, source, layout, size,
 * color, and position based on the image number provided from the picture table.
 * 
 * @param image_number The index of the image in the picture table to be drawn.
 */
void Boardoza_FT810::drawImage(uint16_t x, uint16_t y) {
    write32(RAM_CMD + cmdOffset, BITMAP_HANDLE(0));

	cmdOffset = incrementCMDOffset(cmdOffset, 4);

	write32(RAM_CMD + cmdOffset, BITMAP_SOURCE(0));

	cmdOffset = incrementCMDOffset(cmdOffset, 4);

	write32(RAM_CMD + cmdOffset, BITMAP_LAYOUT(ARGB1555, 680, 156));

	cmdOffset = incrementCMDOffset(cmdOffset, 4);

	write32(RAM_CMD + cmdOffset, BITMAP_SIZE(NEAREST, BORDER, BORDER, 340, 156));

	cmdOffset = incrementCMDOffset(cmdOffset, 4);

    write32(RAM_CMD + cmdOffset, (DL_COLOR_RGB | BLUE| RED| GREEN));

    cmdOffset = incrementCMDOffset(cmdOffset, 4);

 	write32(RAM_CMD + cmdOffset, (BEGIN(BITMAPS)));

 	cmdOffset = incrementCMDOffset(cmdOffset, 4);

    write32(RAM_CMD + cmdOffset, COLOR_A(255) );

    cmdOffset = incrementCMDOffset(cmdOffset, 4);

 	write32(RAM_CMD + cmdOffset, VERTEX2F(x,y));

 	cmdOffset = incrementCMDOffset(cmdOffset, 4);

 	write32(RAM_CMD + cmdOffset, END());

 	cmdOffset = incrementCMDOffset(cmdOffset, 4);

	write32(RAM_CMD + cmdOffset, TAG_MASK(0));
	cmdOffset = incrementCMDOffset(cmdOffset, 4);
}

/**
 * @brief Copies a raw bitmap from ESP32 flash to FT810 graphics memory.
 *
 * This uses a single SPI transaction so the Boardoza UI images can be loaded
 * during setup without slowing down normal screen refreshes.
 */
void Boardoza_FT810::loadBitmap(uint32_t address, const uint8_t* pixels, uint32_t byteCount) {
    if (pixels == nullptr || byteCount == 0) {
        return;
    }

    digitalWrite(csPin, LOW);
    SPI.transfer((uint8_t)(address >> 16) | MEM_WRITE);
    SPI.transfer((uint8_t)(address >> 8));
    SPI.transfer((uint8_t)address);

    for (uint32_t index = 0; index < byteCount; index++) {
        SPI.transfer(pixels[index]);
    }

    digitalWrite(csPin, HIGH);
}

/**
 * @brief Draws an ARGB1555 bitmap previously loaded into FT810 RAM_G.
 *
 * A non-zero touchTag keeps photo icons part of their parent touch button.
 */
void Boardoza_FT810::drawBitmap(
    uint32_t address,
    uint16_t width,
    uint16_t height,
    uint16_t x,
    uint16_t y,
    uint8_t touchTag) {
    if (width == 0 || height == 0) {
        return;
    }

    write32(RAM_CMD + cmdOffset, BITMAP_HANDLE(0));
    cmdOffset = incrementCMDOffset(cmdOffset, 4);
    write32(RAM_CMD + cmdOffset, BITMAP_SOURCE(address));
    cmdOffset = incrementCMDOffset(cmdOffset, 4);
    write32(RAM_CMD + cmdOffset, BITMAP_LAYOUT(ARGB1555, width * 2, height));
    cmdOffset = incrementCMDOffset(cmdOffset, 4);
    write32(RAM_CMD + cmdOffset, BITMAP_SIZE(NEAREST, BORDER, BORDER, width, height));
    cmdOffset = incrementCMDOffset(cmdOffset, 4);
    write32(RAM_CMD + cmdOffset, BLEND_FUNC(SRC_ALPHA, ONE_MINUS_SRC_ALPHA));
    cmdOffset = incrementCMDOffset(cmdOffset, 4);
    write32(RAM_CMD + cmdOffset, COLOR_RGB(255, 255, 255));
    cmdOffset = incrementCMDOffset(cmdOffset, 4);
    write32(RAM_CMD + cmdOffset, COLOR_A(255));
    cmdOffset = incrementCMDOffset(cmdOffset, 4);

    if (touchTag != 0) {
        write32(RAM_CMD + cmdOffset, TAG_MASK(1));
        cmdOffset = incrementCMDOffset(cmdOffset, 4);
        write32(RAM_CMD + cmdOffset, TAG(touchTag));
        cmdOffset = incrementCMDOffset(cmdOffset, 4);
    }

    write32(RAM_CMD + cmdOffset, BEGIN(BITMAPS));
    cmdOffset = incrementCMDOffset(cmdOffset, 4);
    write32(RAM_CMD + cmdOffset, VERTEX2II(x, y, 0, 0));
    cmdOffset = incrementCMDOffset(cmdOffset, 4);
    write32(RAM_CMD + cmdOffset, END());
    cmdOffset = incrementCMDOffset(cmdOffset, 4);

    if (touchTag != 0) {
        write32(RAM_CMD + cmdOffset, TAG_MASK(0));
        cmdOffset = incrementCMDOffset(cmdOffset, 4);
    }
}

/**
 * @brief Loads an image into memory based on the specified image number.
 *
 * This function loads an image into memory by determining the size of the image data based on the image number provided.
 * It then inflates the image data and writes it into the command buffer, ensuring the image is correctly loaded for display.
 * 
 * @param image_number The index of the image data to be loaded (0: product1, 1: product2, 2: product3, 3: logo_boardoza).
 */
void Boardoza_FT810::loadImage() {

    unsigned long size_pic=0;
	unsigned long i=0;
	unsigned long k=0;
	unsigned int x=0;
	unsigned int y=0;

    waitForCommandCompletion();

	cmdOffset = cmdBufferWrite;                        // The new starting point the first location after the last command

    size_pic=sizeof(logo_boardoza);

	size_pic = (size_pic + 3)&(~3);

	x=size_pic/4000;

	y=size_pic-(x*4000);

    write32(RAM_CMD + cmdOffset, CMD_INFLATE);

    cmdOffset = incrementCMDOffset(cmdOffset, 4);

    write32(RAM_CMD + cmdOffset, 0);

    cmdOffset = incrementCMDOffset(cmdOffset, 4);

    for(k=0;k<x;k++)
    {
		for(i=(k*4000);i<((k+1)*4000);i++)
		{
		    write8(RAM_CMD + cmdOffset, logo_boardoza[i]);

			cmdOffset = incrementCMDOffset(cmdOffset, 1);
		}
		write16(REG_CMD_WRITE, (cmdOffset));

        waitForCommandCompletion();
    }

    for(i=0;i<y;i++)
    {

	    write8(RAM_CMD + cmdOffset, logo_boardoza[i+(x * 4000)]);

	    cmdOffset = incrementCMDOffset(cmdOffset, 1);
    }

    write16(REG_CMD_WRITE, (cmdOffset));

    waitForCommandCompletion();

}

