/**
 * @brief Plays audio playback with specific configurations.
 *
 * @details This function configures and starts audio playback with specific settings.
 * It sets the volume, start position, length, frequency, format, loop, and play parameters for audio playback on the FT810 sound module.
 *
 * @note This function is used to initiate audio playback with predefined settings on the FT810 sound module. 
 * It configures the volume, start position, length, frequency, format, loop, and play parameters for the playback operation.
 */
void Boardoza_FT810::play_audio_playback()
{
    write_sound_reg_vol_pb(0x000000FF);
    write_sound_reg_playback_start(0);
    write_sound_reg_playback_length(100*1024);
    write_sound_reg_playback_freq(44100);
    write_sound_reg_playback_format(ULAW_SAMPLES);
    write_sound_reg_playback_loop(1);
    write_sound_reg_playback_play(1);
}

/**
 * @brief Plays a sound synthesizer with specific configurations.
 *
 * @details This function configures and starts a sound synthesizer with specific settings.
 * It sets the volume, sound parameters, and initiates the sound playback on the FT810 sound module.
 *
 * @note This function is used to initiate sound synthesis with predefined settings on the FT810 sound module.
 * It configures the volume, sound parameters, and starts the sound playback operation.
 */
void Boardoza_FT810::play_sound_synthesizer()
{
    write_sound_reg_vol_sound(0x00000010);
    write_sound_reg_sound( (0x6C<< 8) | 0x0008);
    //write_sound_reg_sound(0x0005);
    write_sound_reg_play(1);
    
}

/**
 * @brief Returns the X position of a touch event on a capacitive touchscreen.
 *
 * @param addressX The I2C address for reading the X position of the touch event.
 * @return The X position of the touch event on the capacitive touchscreen.
 *
 * @details This function reads the X position of a touch event on a capacitive touchscreen using the specified I2C address.
 * It processes the raw data read from the address to extract the X position and determine the frame number of the touch event.
 * It returns the X position of the touch event, or 0 if the event is not valid.
 */
uint16_t Boardoza_FT810::touchXPosition(uint8_t addressX) {
    uint16_t temp_event = 0;
    uint16_t value = 0;
    uint16_t temp_value = 0;

    value = read_i2c_register(addressX);
    value = value << 8;
    value |= read_i2c_register(addressX + 1);
    
    temp_event = value >> 14;
    
    value = value & 0x0FFF;

    if(temp_event != 3) {
        return value;
    } else {
        return 0;
    }
}

/**
 * @brief Returns the Y position of a touch event on a capacitive touchscreen.
 *
 * @param addressY The I2C address for reading the Y position of the touch event.
 * @return The Y position of the touch event on the capacitive touchscreen.
 *
 * @details This function reads the Y position of a touch event on a capacitive touchscreen using the specified I2C address.
 * It processes the raw data read from the address to extract the Y position and identify the touch event ID. It returns the Y position of the touch event.
 */
uint16_t Boardoza_FT810::touchYPosition(uint8_t addressY) {
    uint16_t temp_id = 0;
    uint16_t value = 0;
    uint16_t temp_value = 0;

    value = read_i2c_register(addressY);
    value = value << 8;
    value |= read_i2c_register(addressY + 1);
    
    temp_id = value >> 12;
    
    value = value & 0x0FFF;
    
    return value;
}

/**
 * @brief Returns the touch weight value on a capacitive touchscreen.
 *
 * @param addressWeight The I2C address for reading the touch weight value.
 * @return The touch weight value on the capacitive touchscreen (1-15).
 *
 * @details This function reads the touch weight value on a capacitive touchscreen using the specified I2C address.
 * It returns the touch weight value as an 8-bit unsigned integer, ranging from 1 to 15.
 */
uint8_t Boardoza_FT810::touchWeight(uint8_t addressWeight) {
    return read_i2c_register(addressWeight);
}

/**
 * @brief Returns the touch miscellaneous value related to the area covered on the touchscreen.
 *
 * @param addressMisc The I2C address for reading the touch miscellaneous value.
 * @return The touch miscellaneous value related to the area covered on the touchscreen.
 *
 * @details This function reads the touch miscellaneous value related to the area covered on the touchscreen using the specified I2C address.
 * It returns the miscellaneous value as an 8-bit unsigned integer, where the value is obtained by shifting the raw data read from the address right by 4 bits.
 */
uint8_t Boardoza_FT810::touchMisc(uint8_t addressMisc) {
    return read_i2c_register(addressMisc)>>4;
}

uint8_t toggle = 1;
uint8_t filter = 4;
uint8_t intvalue = 0x00;
uint8_t pre_intvalue = 0xFF;

/**
 * @brief Toggles the touch filter and updates the display accordingly.
 *
 * This function toggles the touch filter based on the interrupt pin value and updates the display to show the current toggle state. 
 *
 * It checks the interrupt pin value and compares it with the previous value to determine if a toggle action is needed. 
 * If the filter is active, it decrements the filter value. If the filter value reaches 0, it performs the toggle action.
 * The function updates the toggle state and displays the toggle button accordingly.
 * 
 * @note This function assumes that the necessary variables (filter, toggle, intvalue, pre_intvalue) are defined and initialized appropriately.
 *       Ensure that the necessary variables are properly set before calling this function.
 */
void Boardoza_FT810::touchToggleFilter() {
    uint8_t temp_intvalue = digitalRead(interruptPin);
    if (temp_intvalue!=pre_intvalue) {
      if (filter) {
        filter--;
        }
      else {
        intvalue=temp_intvalue;
        pre_intvalue=temp_intvalue;
        if (!intvalue)
          {
          if (toggle) toggle=0;
          else toggle=1;
          }
        }
    }
  else
    {
    filter=2;
    }    
  if(toggle) {
    drawToggle(60, 20, 66, 27, 0, TOGGLE_ON, "ON");
  } else {
    drawToggle(60, 20, 66, 27, 0, TOGGLE_OFF, "OFF");
  }
}

/**
 * @brief Reads a register value from an I2C device.
 *
 * @param reg The register address to read from the I2C device.
 * @return The value read from the specified register of the I2C device.
 *
 * @details This function initiates communication with the I2C device at the specified address
 * writes the register address to be read, and reads the value from that register.
 * It returns the value read as an unsigned 32-bit integer.
 */
uint32_t Boardoza_FT810::read_i2c_register(uint8_t reg) {
    Wire.beginTransmission(touch_address);
    Wire.write(reg);
    Wire.endTransmission(false);
    Wire.requestFrom(touch_address, 1);
    return Wire.read();
}

/**
 * @brief Writes a value to a register of an I2C device.
 *
 * @param reg The register address to write to in the I2C device.
 * @param value The value to write to the specified register.
 *
 * @details This function initiates communication with the I2C device at the specified address
 * writes the register address and the value to be written, and ends the transmission.
 */
void Boardoza_FT810::write_i2c_register(uint8_t reg, uint8_t value) {
    Wire.beginTransmission(touch_address);
    Wire.write(reg);
    Wire.write(value);
    Wire.endTransmission(true);
}

